//###########################################################
getWeekKey = function(date, weekDayIndex) {
  var monday;
  monday = new Date(date);
  monday.setDate(monday.getDate() - weekDayIndex);
  return 10000 * monday.getFullYear() + 100 * (monday.getMonth() + 1) + monday.getDate();
};

//###########################################################
extractRelevantHistory = function(history, toAge) {
  var age, result, runLimit;
  result = [];
  age = 0;
  runLimit = toAge + 1;
  while (age < runLimit) {
    if (history[age] == null) {
      break;
    }
    result.push(history[age]);
    age++;
  }
  return result;
};

