repairHLC = function(hlc) {
  switch (false) {
    // case we got correct hlc
    case !(hlc[0] >= hlc[2] && hlc[0] >= hlc[1] && hlc[2] >= hlc[1]):
      return hlc;
    
      // case we got more something like hcl
    case !(hlc[0] >= hlc[2] && hlc[0] >= hlc[1] && hlc[1] >= hlc[2]):
      return [hlc[0], hlc[2], hlc[1]];
    // case we got more something like lhc
    case !(hlc[1] >= hlc[2] && hlc[1] >= hlc[0] && hlc[2] >= hlc[0]):
      return [hlc[1], hlc[0], hlc[2]];
    // case we got more something like lch
    case !(hlc[2] >= hlc[1] && hlc[2] >= hlc[0] && hlc[1] >= hlc[0]):
      return [hlc[2], hlc[0], hlc[1]];
    // case we got more something like chl
    case !(hlc[1] >= hlc[2] && hlc[1] >= hlc[0] && hlc[0] >= hlc[2]):
      return [hlc[1], hlc[2], hlc[0]];
    // case we got more something like clh
    case !(hlc[2] >= hlc[1] && hlc[2] >= hlc[0] && hlc[0] >= hlc[1]):
      return [hlc[2], hlc[1], hlc[0]];
    default:
      console.error(`repairHLC - impossible case for [${hlc}]`);
  }
  return hlc;
};
